//! Parity with AutoDock Vina 1.2.7 on a fixed set of PoseBusters complexes.
//!
//! The fixtures in `tests/parity_data/` and Vina's scores in `golden.tsv`
//! are generated by `benchmark/parity/make_golden.py`. The scoring tests are
//! fast and always run; the docking test is `#[ignore]`d and run in release
//! mode by CI: `cargo test --release --test parity -- --ignored`.

use nalgebra::Vector3;
use rustdock_vina::forcefield::vina::VinaForceField;
use rustdock_vina::forcefield::vinardo::VinardoForceField;
use rustdock_vina::forcefield::ForceField;
use rustdock_vina::io::{parse_flex_pdbqt, parse_pdbqt};
use rustdock_vina::optimization::monte_carlo::{MonteCarlo, MonteCarloParams};
use rustdock_vina::scoring::{score_pose, score_pose_with_flex};
use rustdock_vina::{FlexResidues, Molecule};
use std::collections::HashMap;
use std::path::PathBuf;

/// Largest difference from Vina allowed for a score, in kcal/mol. On these
/// fixtures rustdock is within 0.016 of Vina's three printed decimals, so a
/// 0.3% change to one Vina weight already fails.
const SCORE_TOLERANCE: f64 = 0.02;

/// How much worse than Vina's top affinity rustdock's may be when docking.
const DOCK_AFFINITY_SLACK: f64 = 0.3;

/// Success threshold for the top pose's heavy-atom RMSD to the crystal pose.
const DOCK_RMSD_LIMIT: f64 = 2.0;

fn data_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("parity_data")
}

/// One row of `golden.tsv`: column name to value.
struct Complex(HashMap<String, String>);

impl Complex {
    fn code(&self) -> &str {
        &self.0["code"]
    }

    fn value(&self, column: &str) -> f64 {
        self.0[column]
            .parse()
            .unwrap_or_else(|_| panic!("{}: bad {column}: {:?}", self.code(), self.0[column]))
    }

    fn vector(&self, prefix: &str) -> Vector3<f64> {
        Vector3::new(
            self.value(&format!("{prefix}_x")),
            self.value(&format!("{prefix}_y")),
            self.value(&format!("{prefix}_z")),
        )
    }

    fn docked(&self) -> bool {
        self.0["dock"] == "True"
    }

    /// Whether the complex has flexible side chains (`flex.pdbqt`).
    fn flexible(&self) -> bool {
        self.0.get("flex_residues").is_some_and(|r| !r.is_empty())
    }

    fn load(&self, file: &str) -> Molecule {
        let path = data_dir().join(self.code()).join(file);
        parse_pdbqt(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
    }

    /// The rigid receptor and flexible side chains.
    fn load_flex(&self) -> (Molecule, FlexResidues) {
        let rigid = self.load("flex_rigid.pdbqt");
        let path = data_dir().join(self.code()).join("flex.pdbqt");
        let flex =
            parse_flex_pdbqt(&path, &rigid).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        (rigid, flex)
    }

    /// Whether Vina docked the complex with its flexible side chains.
    fn flex_docked(&self) -> bool {
        self.0
            .get("vina_flex_dock_affinity")
            .is_some_and(|v| !v.is_empty())
    }
}

fn golden() -> Vec<Complex> {
    let text = std::fs::read_to_string(data_dir().join("golden.tsv")).expect("golden.tsv");
    let mut lines = text.lines();
    let header: Vec<&str> = lines.next().expect("header").split('\t').collect();
    lines
        .map(|line| {
            Complex(
                header
                    .iter()
                    .zip(line.split('\t'))
                    .map(|(k, v)| (k.to_string(), v.to_string()))
                    .collect(),
            )
        })
        .collect()
}

/// Scores `ligand` of every complex and compares the intermolecular energy and
/// affinity with Vina's `<prefix>_inter` and `<prefix>_affinity`, reporting
/// every mismatch at once.
fn check_scores(forcefield: &dyn ForceField, ligand: &str, prefix: &str) {
    let complexes = golden();
    assert!(complexes.len() >= 15, "golden.tsv has too few complexes");
    let mut failures = Vec::new();
    for complex in &complexes {
        let receptor = complex.load("receptor.pdbqt");
        let pose = complex.load(ligand);
        let score = score_pose(&pose, &receptor, forcefield).expect("score");
        for (name, ours) in [
            ("inter", score.intermolecular),
            ("affinity", score.affinity),
        ] {
            let vina = complex.value(&format!("{prefix}_{name}"));
            if (ours - vina).abs() > SCORE_TOLERANCE {
                failures.push(format!(
                    "{} {name}: rustdock {ours:.3}, Vina {vina:.3} (diff {:+.3})",
                    complex.code(),
                    ours - vina
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} {ligand} scores differ from Vina 1.2.7 by more than {SCORE_TOLERANCE}:\n  {}",
        forcefield.name(),
        failures.join("\n  ")
    );
}

/// Scores the crystal pose of every complex with flexible side chains and
/// compares each energy term with Vina's `<scoring>_flex_*` columns.
fn check_flex_scores(forcefield: &dyn ForceField, scoring: &str) {
    let complexes: Vec<_> = golden().into_iter().filter(Complex::flexible).collect();
    assert!(
        complexes.len() >= 5,
        "golden.tsv has too few flex complexes"
    );
    let mut failures = Vec::new();
    for complex in &complexes {
        let (rigid, flex) = complex.load_flex();
        let pose = complex.load("ligand_xtal.pdbqt");
        let score = score_pose_with_flex(&pose, &rigid, Some(&flex), forcefield).expect("score");
        for (name, ours) in [
            ("inter", score.intermolecular),
            ("affinity", score.affinity),
            ("lig_flex", score.ligand_flex),
            ("flex_rec", score.flex_receptor),
            ("flex_flex", score.flex_flex),
        ] {
            let vina = complex.value(&format!("{scoring}_flex_{name}"));
            if (ours - vina).abs() > SCORE_TOLERANCE {
                failures.push(format!(
                    "{} {name}: rustdock {ours:.3}, Vina {vina:.3} (diff {:+.3})",
                    complex.code(),
                    ours - vina
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} flex scores differ from Vina 1.2.7 by more than {SCORE_TOLERANCE}:\n  {}",
        forcefield.name(),
        failures.join("\n  ")
    );
}

#[test]
fn crystal_scores_match_vina() {
    check_scores(&VinaForceField::default(), "ligand_xtal.pdbqt", "vina_xtal");
}

#[test]
fn crystal_scores_match_vinardo() {
    check_scores(
        &VinardoForceField::default(),
        "ligand_xtal.pdbqt",
        "vinardo_xtal",
    );
}

#[test]
fn crystal_flex_scores_match_vina() {
    check_flex_scores(&VinaForceField::default(), "vina");
}

#[test]
fn crystal_flex_scores_match_vinardo() {
    check_flex_scores(&VinardoForceField::default(), "vinardo");
}

/// Vina's own top docked pose, read from its output, scores as Vina scores it.
#[test]
fn vina_poses_rescore() {
    check_scores(&VinaForceField::default(), "vina_top.pdbqt", "vina_top");
}

/// Heavy-atom RMSD in atom order, without superposition.
fn heavy_rmsd(a: &Molecule, b: &Molecule) -> f64 {
    let heavy = |m: &Molecule| -> Vec<Vector3<f64>> {
        m.atoms
            .iter()
            .filter(|atom| !atom.atom_type.is_hydrogen())
            .map(|atom| atom.coordinates)
            .collect()
    };
    let (a, b) = (heavy(a), heavy(b));
    assert_eq!(a.len(), b.len(), "heavy atom counts differ");
    let sum: f64 = a.iter().zip(&b).map(|(p, q)| (p - q).norm_squared()).sum();
    (sum / a.len() as f64).sqrt()
}

/// Docking from an RDKit conformer finds the crystal pose, as Vina does.
///
/// The thresholds are loose on purpose: floating-point differences between
/// CPUs can change a search's trajectory, so this guards against search
/// regressions rather than checking exact poses.
#[test]
#[ignore = "slow in debug builds; CI runs it with --release -- --ignored"]
fn docking_finds_crystal_pose() {
    let forcefield = VinaForceField::default();
    let optimizer = MonteCarlo::with_params(MonteCarloParams {
        seed: Some(42),
        ..MonteCarloParams::default()
    });
    let docked: Vec<_> = golden().into_iter().filter(Complex::docked).collect();
    assert!(!docked.is_empty(), "golden.tsv has no docking complexes");

    let mut failures = Vec::new();
    for complex in &docked {
        let receptor = complex.load("receptor.pdbqt");
        let ligand = complex.load("ligand_start.pdbqt");
        let crystal = complex.load("ligand_xtal.pdbqt");
        let target = optimizer
            .target(
                receptor,
                &forcefield,
                complex.vector("center"),
                complex.vector("size"),
            )
            .expect("target");
        let results = optimizer
            .dock_into(&target, &ligand, &forcefield, 9, 0)
            .expect("dock");
        let top = results.first().expect("at least one pose");
        let affinity =
            forcefield.apply_torsional_normalization(top.energy, ligand.vina_torsion_count());
        let rmsd = heavy_rmsd(&top.molecule, &crystal);
        let vina = complex.value("vina_dock_affinity");
        println!(
            "{}: affinity {affinity:.3} (Vina {vina:.3}), top-1 RMSD {rmsd:.2} A (Vina {:.2})",
            complex.code(),
            complex.value("vina_dock_rmsd")
        );
        if rmsd >= DOCK_RMSD_LIMIT {
            failures.push(format!("{}: top-1 RMSD {rmsd:.2} A", complex.code()));
        }
        if affinity > vina + DOCK_AFFINITY_SLACK {
            failures.push(format!(
                "{}: affinity {affinity:.3}, Vina {vina:.3}",
                complex.code()
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Docking with flexible side chains reaches Vina's top affinity, and on the
/// complex where Vina also finds the crystal pose (`flex_dock`), so does
/// rustdock.
#[test]
#[ignore = "slow in debug builds; CI runs it with --release -- --ignored"]
fn flex_docking_matches_vina() {
    let forcefield = VinaForceField::default();
    let optimizer = MonteCarlo::with_params(MonteCarloParams {
        seed: Some(42),
        ..MonteCarloParams::default()
    });
    let docked: Vec<_> = golden().into_iter().filter(Complex::flex_docked).collect();
    assert!(
        !docked.is_empty(),
        "golden.tsv has no flex docking complexes"
    );
    assert!(docked.iter().any(|c| c.0["flex_dock"] == "True"));

    let mut failures = Vec::new();
    for complex in &docked {
        let (rigid, flex) = complex.load_flex();
        let ligand = complex.load("ligand_start.pdbqt");
        let crystal = complex.load("ligand_xtal.pdbqt");
        let target = optimizer
            .target_with_flex(
                rigid,
                flex,
                &forcefield,
                complex.vector("flex_center"),
                complex.vector("flex_size"),
            )
            .expect("target");
        let results = optimizer
            .dock_into(&target, &ligand, &forcefield, 9, 0)
            .expect("dock");
        let top = results.first().expect("at least one pose");
        assert!(
            top.flex.is_some(),
            "{}: no side chains in the result",
            complex.code()
        );
        let affinity =
            forcefield.apply_torsional_normalization(top.energy, ligand.vina_torsion_count());
        let rmsd = heavy_rmsd(&top.molecule, &crystal);
        let vina = complex.value("vina_flex_dock_affinity");
        println!(
            "{}: affinity {affinity:.3} (Vina {vina:.3}), top-1 RMSD {rmsd:.2} A (Vina {:.2})",
            complex.code(),
            complex.value("vina_flex_dock_rmsd")
        );
        if complex.0["flex_dock"] == "True" && rmsd >= DOCK_RMSD_LIMIT {
            failures.push(format!("{}: top-1 RMSD {rmsd:.2} A", complex.code()));
        }
        if affinity > vina + DOCK_AFFINITY_SLACK {
            failures.push(format!(
                "{}: affinity {affinity:.3}, Vina {vina:.3}",
                complex.code()
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
